// import React from "react";
import './calcStyles.css';
import './ButtonColor.css';

import React, { Component } from 'react'

export class Calculator extends Component {
  state = {
    currentTheme: 1,
    currentSymbol: '+',
    activeInputScore: '',
    secondaryInputScore: ''
  }
  changeInput = (currNum) => {
    this.setState({ activeInputScore: currNum.target.value })
  }
  changeTheme(theme) {
    this.setState({
      currentTheme: theme
    })
    // console.log("body---" + this.state.currentTheme)
  }

  reset = () => {
    this.setState({ activeInputScore: '', secondaryInputScore: '' })
  }

  del = () => {
    this.setState({ activeInputScore: '' })
  }

  getNum = () => {

    let a = this.activeInputScore;
    let b = this.secondaryInputScore;
    let result = 0;


    switch (this.currentSymbol) {
      case "+":
        result = this.sum(a, b);
        break;
      case "-":
        result = this.subtract(a, b);
        break;
      case "*":
        result = this.multiply(a, b);
        break;
      case "/":
        result = this.division(a, b);
        break;

      default:
        result = 0;
        break;
    }

    this.setState({
      secondaryInputScore: a,
      activeInputScore: result
    });



    // this.setState({ secondaryInputScore: this.state.activeInputScore })
    if (this.sum) {
      this.setState({ activeInputScore: Number(this.state.secondaryInputScore) + Number(this.state.activeInputScore), secondaryInputScore: this.state.activeInputScore })
      console.log("NADA")
    }
    if (this.multiply) {
      this.setState({ activeInputScore: Number(this.state.secondaryInputScore) * Number(this.state.activeInputScore), secondaryInputScore: this.state.activeInputScore })
    }
    if (this.division) {
      this.setState({ activeInputScore: Number(this.state.secondaryInputScore) / Number(this.state.activeInputScore), secondaryInputScore: this.state.activeInputScore })
    }
    if (this.subtract) {
      this.setState({ activeInputScore: Number(this.state.secondaryInputScore) - Number(this.state.activeInputScore), secondaryInputScore: this.state.activeInputScore })
    }
  }

  // sum = (a, b) => {
  //   return a + b;
  // }

  sum = () => {
    // return a + 
    let sum = 0;
    this.setState({ secondaryInputScore: this.state.activeInputScore, activeInputScore: ' ' });
    sum = this.state.activeInputScore + this.state.secondaryInputScore;
    console.log(sum)
  }

  subtract = () => {
    let minus = 0;
    // this.state.secondaryInputScore = this.state.activeInputScore;
    this.setState({ secondaryInputScore: this.state.activeInputScore, activeInputScore: ' ' });
    minus = this.state.activeInputScore - this.state.secondaryInputScore;
    console.log(minus)
  }

  division = () => {
    let divide = 0;
    // this.state.secondaryInputScore = this.state.activeInputScore;
    this.setState({ secondaryInputScore: this.state.activeInputScore, activeInputScore: ' ' });
    divide = this.state.activeInputScore / this.state.secondaryInputScore;
    console.log(divide)
  }

  multiply = () => {
    let mutiply = 0;
    // this.state.secondaryInputScore = this.state.activeInputScore;
    this.setState({ secondaryInputScore: this.state.activeInputScore, activeInputScore: ' ' });
    mutiply = this.state.activeInputScore * this.state.secondaryInputScore;
    console.log(mutiply)
  }
  showSymbol(e) {
    e.preventDefault()
    console.log(e.target.innerHTML)
  }
  render() {
    return (
      <div className={"body---" + this.state.currentTheme}>
        {/* <div className={"body---" + this.state.currentTheme}> */}
        <div className={"box---" + this.state.currentTheme}>
          <div className="container">
            <div className="txt">calc</div>
            <div className={"form-switch-a---" + this.state.currentTheme} data-toggle="radio" role="group">
              <p className="themeToggle">theme</p>
              <label className="new-button" onClick={() => { this.changeTheme(1) }}>
                <div className="numAlign">1</div>
                <input type="radio" name="options" id="option1" defaultChecked />
                <div className={"dot-check---" + this.state.currentTheme}></div>
              </label>
              <label className="new-button" onClick={() => { this.changeTheme(2) }}>
                <div className="numAlign">2</div>
                <input type="radio" name="options" id="option2" />
                <div className={"dot-check---" + this.state.currentTheme}></div>
              </label>
              <label className="new-button" onClick={() => { this.changeTheme(3) }}>
                <div className="numAlign">3</div>
                <input type="radio" name="options" id="option3" />
                <div className={"dot-check---" + this.state.currentTheme}></div>
              </label>
            </div>
          </div>

          <main className="calcPortion">
            <div className="row">
              <div className={"row---" + this.state.currentTheme}>
                <input type="number" name="num" id="#" maxLength="2" max="7" min="3" value={this.state.activeInputScore} onChange={this.changeInput} />
                <div className="inputScore">{this.state.secondaryInputScore}</div>
                <div className="currSign">{this.state.currentSymbol}</div>
              </div>
              <div className={"row2---" + this.state.currentTheme}>
                <button className={"button---" + this.state.currentTheme}>7</button>
                <button className={"button---" + this.state.currentTheme}>8</button>
                <button className={"button---" + this.state.currentTheme}>9</button>
                <button className={"button---" + this.state.currentTheme + " item4---" + this.state.currentTheme} onClick={this.del}>DEL</button>
                <button className={"button---" + this.state.currentTheme}>4</button>
                <button className={"button---" + this.state.currentTheme}>5</button>
                <button className={"button---" + this.state.currentTheme}>6</button>
                <button className={"button---" + this.state.currentTheme} onClick={this.sum}>+</button>
                <button className={"button---" + this.state.currentTheme}>1</button>
                <button className={"button---" + this.state.currentTheme}>2</button>
                <button className={"button---" + this.state.currentTheme}>3</button>
                <button className={"button---" + this.state.currentTheme} onClick={this.subtract}>-</button>
                <button className={"button---" + this.state.currentTheme}>.</button>
                <button className={"button---" + this.state.currentTheme}>0</button>
                <button className={"button---" + this.state.currentTheme} onClick={this.division}>/</button>
                <button className={"button---" + this.state.currentTheme} onClick={this.multiply}>*</button>
                <button className={"button---" + this.state.currentTheme + " item17---" + this.state.currentTheme} onClick={this.reset}>RESET</button>
                <button className={"button---" + this.state.currentTheme + " item18---" + this.state.currentTheme} onClick={this.getNum}>=</button>
              </div>
            </div>
          </main>
        </div>
      </div>

    )
  }
}

export default Calculator
